import {GHANA_LEVELS} from '../../../shared/ghana-curriculum.js';
// Original, reusable teaching units. Class variants use explicit scaffolding; they are not official term mappings.
// Row fields: topic, observable outcome, model and practice, individual task, teacher check.
const englishLower=[
 ['Listening to directions','Follow and explain a short classroom direction.','Model: Put the blue book beside the cup. Partners give and follow directions using safe classroom objects, then swap roles. Contrast beside and behind using a toy.','Place a pencil under a book and explain where it is.','Check the position as well as the spoken phrase; accept a gesture before supporting a full sentence.'],
 ['Speaking in complete ideas','Introduce a person or object using a clear sentence.','Use an original model: This is Abena. She likes drawing. Learners describe an imagined character from a picture and ask one polite question.','Describe a pictured child using two connected ideas.','Look for understandable meaning and a suitable naming word; do not require disclosure of personal information.'],
 ['Hearing and building words','Blend and segment familiar spoken words.','Say sun slowly, blending /s/ /u/ /n/. Use counters for sounds, then connect the sounds to s, u and n. Compare sun and run. Avoid adding an extra vowel to each consonant sound.','Blend /m/ /a/ /t/ and identify the first sound in sun.','Expected mat and /s/. Adjust pronunciation modelling for the classroom language and use familiar vocabulary.'],
 ['Reading a short narrative','Identify a character, action and setting from a short text.','Read this original text: Ama has a red bag. She puts a book in it. She walks to class. Model pointing to evidence; pairs retell using picture cards.','Who has the bag? What goes inside it?','Ama; a book. Learners should use the text rather than infer an unsupported object.'],
 ['Naming words','Identify nouns for people, places and things.','Sort child, market, cup, teacher, school and drum into illustrated groups. Use each word in an oral sentence and explain that words can have different uses in context.','Find the naming words in The teacher carries a bag.','Teacher and bag. Accept the as an article rather than a naming word.'],
 ['Action words','Use an appropriate verb to describe an action.','Act or point to pictures for read, carry and draw. Build sentences such as Kofi draws a tree. Partners choose a verb that matches a picture.','Complete The children ___ a song with a suitable action word.','Sing is a sensible choice; check agreement in the complete sentence.'],
 ['Describing objects','Use an adjective to make a description more precise.','Compare a small cup and a large cup using pictures. Read: Esi holds a small green cup. Pairs choose descriptions that identify an object without judging people’s bodies.','Name two describing words in a small green cup.','Small and green.'],
 ['Sentence boundaries','Write a simple sentence with a capital letter and a full stop.','Model repairing ama reads a book. Discuss the name capital and sentence ending. Pairs build new sentences using word cards before writing.','Rewrite kofi has a pen with appropriate capitals and ending.','Kofi has a pen. Check spacing and meaning as well as punctuation.'],
 ['Sequencing events','Retell three events in a sensible order.','Use this original sequence: A seed is put in soil. Water is added. A shoot appears later. Learners order pictures and use first, next and later without claiming growth occurs instantly.','Retell the three events using sequencing words.','The order should be planting, watering, then later growth; accept different grammatical forms with clear meaning.'],
 ['Reading an information text','Retrieve two facts from a short information text.','Read: A tree has roots, a stem and leaves. Roots take in water. Leaves help the plant make food. Pairs label a simple tree picture using the text.','Which part takes in water? Name one other part.','Roots; stem or leaves.'],
 ['Writing a short description','Plan and write connected sentences about a familiar object.','Use a pictured bag. Model planning its colour, use and contents, then write three original sentences. Pairs give feedback on whether the sentences describe the same object.','Write two or three sentences describing an imagined school bag.','Look for relevant details, readable sentence boundaries and consistent meaning; spelling support may be offered.'],
 ['A class reading and speaking showcase','Read or retell a short text and explain one writing improvement.','Learners select an original paragraph from the unit, practise with a partner and present it using speech, pointing or a communication aid. Revise a sentence after feedback.','Read or retell the Ama story and improve one unpunctuated sentence.','Check understanding separately from decoding and confidence. Record one next step for each learner.'],
];
const englishUpper=[
 ['Listening for main ideas','Summarize a short spoken message without adding unsupported details.','Read twice: Our class will care for a small garden. On Tuesday we will label the plants. We will record changes each Friday. Learners note key actions and distinguish them from invented details.','State the main purpose and one planned action.','Caring for and observing the garden; labelling on Tuesday or recording on Friday are supported details.'],
 ['Asking useful questions','Ask a relevant open question and respond with an explanation.','Model a fictional interview about keeping a reading corner tidy. Compare Do you like books? with How could we make books easier to find? Partners role-play without collecting personal data.','Write one open question about improving a reading corner.','A how/why/what question inviting an explanation is appropriate; a yes/no question alone does not meet the goal.'],
 ['Narrative comprehension','Support a character inference with textual evidence.','Read: Kojo saw a torn book on the shelf. He put it carefully on the teacher’s desk and wrote a note asking for help to repair it. Discuss actions before inferring attitudes.','What might Kojo value? Give evidence.','He may value books or care for shared resources; evidence is careful handling and asking to repair. Alternative supported inferences are acceptable.'],
 ['Vocabulary in context','Infer a word’s likely meaning and check it against context.','Read: The path was slippery after the rain, so Afua walked slowly. Model using the cause and action rather than guessing from one letter. Pairs compare likely and unlikely meanings.','Explain slippery using a clue from the sentence.','A surface easy to slide on; rain and walking slowly support that meaning.'],
 ['Pronouns and reference','Use pronouns with clear antecedents.','Compare Ama gave Esi her book with Ama gave Esi the book that belonged to Ama. Discuss ambiguity, then replace repeated nouns in a paragraph while keeping references clear.','Improve Kofi told Yaw that he had lost his pen so ownership is clear.','Accept any explicit, consistent owner; the original sentence alone does not establish who lost the pen.'],
 ['Verb tense in narratives','Maintain a suitable tense when recounting an event.','Model Yesterday we visited the garden. We measured a leaf and recorded its length. Partners find an unexplained switch to present tense and revise it.','Rewrite Yesterday Esi walk to class and opens her book in past tense.','Yesterday Esi walked to class and opened her book.'],
 ['Joining ideas','Join related clauses using a meaningful conjunction.','Compare because, but and so using fictional classroom situations. Learners explain the relationship before choosing a word.','Join The rain began and We moved the books indoors using so.','The rain began, so we moved the books indoors. The cause-result relation should remain clear.'],
 ['Paragraph structure','Organize a paragraph around one main idea.','Build an original reading-corner paragraph with a topic sentence, two supporting details and a closing sentence. Identify an unrelated football sentence and explain why it does not fit.','Write a four-sentence paragraph about caring for classroom materials.','Check unity, relevant supporting details and a logical order rather than requiring one exact text.'],
 ['Summarizing information','Write a short summary preserving the main ideas.','Use: A compost pile can contain plant scraps and dry leaves. These materials break down over time. The resulting compost can improve soil. Model a shorter statement without claiming all waste belongs in compost.','Summarize the information in one or two sentences.','Include plant material breaking down over time and a soil benefit; omit invented timing or unsafe waste.'],
 ['Polite functional writing','Write a clear request with audience-appropriate language.','Plan a fictional note asking the teacher to help repair a damaged shelf. Identify who is addressed, the request and a polite closing; do not send the note externally.','Draft a short request for more time to finish a library task.','Check a clear request, respectful tone and relevant reason; do not assess agreement with the request as writing quality.'],
 ['Revising and editing','Improve clarity and correct sentence-level errors.','Give the original draft: our class have a reading corner it is tidy we shares books. Partners first improve meaning and order, then edit capitals, verbs and punctuation.','Produce a clear corrected version.','For example: Our class has a reading corner. It is tidy. We share books. Accept other grammatical versions.'],
 ['An evidence-based presentation','Present an idea and answer a relevant audience question.','Learners prepare a short proposal for a reading corner using an original paragraph, a labelled sketch and two reasons. Peers ask a question and give specific feedback.','Present one proposal and explain why one detail supports it.','Assess organization, understandable evidence and respectful response; allow alternative presentation methods.'],
];
const englishJhs=[
 ['Purpose, audience and register','Choose language appropriate to a stated audience and purpose.','Compare a fictional message to a friend with a formal request to a librarian about the same lost book. Learners explain differences without treating a home language as inferior.','Write two opening sentences for the two audiences.','Look for a relevant change in formality while keeping the meaning and respectful intent.'],
 ['Discussion and elaboration','Ask questions that develop a discussion and respond with reasons.','Use a fictional proposal for a quiet reading area. Partners practise What evidence supports that? and How could everyone access it? Summarize a partner’s view before responding.','Ask an elaborating question and respond to a follow-up.','Questions should invite reasons or detail, and responses should address the actual question.'],
 ['Inference and narrative viewpoint','Distinguish a textual fact from an inference about a narrator.','Read: I kept the old exercise book, although the cover had faded. Inside were the first stories I had written. Discuss how first-person narration shapes what readers know.','State one fact and one supported inference about the narrator.','Fact: the narrator kept the book. Inference: the stories may have personal value. Do not treat the inference as certain.'],
 ['Evaluating informational claims','Separate a claim, supporting evidence and an unsupported assumption.','Use a fictional notice: Our new reading corner increased reading because three pupils said they liked it. Learners identify the conclusion and question whether that evidence measures reading for the class.','Suggest better evidence for the claim.','A defined measure before and after, broader participation and consideration of other influences are sensible improvements.'],
 ['Vocabulary and figurative language','Explain a figurative phrase using context.','Read this original sentence: The classroom became a beehive of ideas as groups planned their displays. Compare the metaphor with a literal description and discuss its effect.','Explain beehive of ideas without treating it literally.','It suggests busy, active collaboration; alternative context-supported interpretations are acceptable.'],
 ['Clauses and sentence variety','Combine clauses while preserving logical relationships.','Compare simple and complex sentences about a fictional project. Model Although the first design failed, the group tested another idea. Partners identify the main idea and concession.','Combine The task was difficult and The group finished it using although.','Although the task was difficult, the group finished it. Accept the reversed clause order with appropriate punctuation.'],
 ['Agreement and consistent tense','Edit a paragraph for subject-verb agreement and purposeful tense.','Use: The group of learners are ready. Each person have a role. Yesterday they presents a plan. Discuss the intended subject and time before editing.','Produce a consistent version describing present readiness and a past presentation.','The group of learners is ready. Each person has a role. Yesterday they presented a plan.'],
 ['Summary and paraphrase','Condense a short source while preserving meaning and attribution.','Use the original information: Shade reduces direct sunlight on a reading area. Seating and clear paths also influence whether learners can use it comfortably. Compare a concise summary with one that invents test results.','Summarize the two design considerations in one sentence.','Mention shade and accessible seating/paths without claiming measured benefits that were not provided.'],
 ['Argument supported by reasons','Develop a claim with relevant reasons and a considered alternative.','Plan a proposal about extending reading time. Include a claim, two reasons and a response to a timetable concern. Use fictional examples rather than invented research statistics.','Write one argument paragraph with a counterpoint.','Check the relationship between claim and reasons, acknowledgment of a concern and a relevant response.'],
 ['Functional correspondence','Draft a formal letter with a clear request and appropriate structure.','Use a fictional class-library request. Model address placeholders using invented details, date, salutation, purpose and closing. Do not submit or send correspondence during the lesson.','Draft the main paragraph requesting permission for a reading event.','A clear request, purpose, relevant details and respectful tone matter more than one fixed wording.'],
 ['Creative writing and revision','Use selected details to develop a short original scene.','Begin with an original prompt: A learner finds a sealed box of old school photographs. Plan setting, a character choice and a consequence without requiring personal disclosure. Peer-review clarity and detail.','Write and revise a short scene with one meaningful character decision.','Assess coherent sequence, purposeful detail and a visible revision, not similarity to a teacher’s story.'],
 ['Presentation and critical response','Present a reasoned proposal and evaluate a response fairly.','Groups present a fictional school-library plan, identify which statements are evidence or assumptions and respond to questions. Require each learner to contribute through an accessible format.','Explain one proposal claim, its support and a limitation.','Look for a clear distinction between evidence and assumption, respectful listening and an honest limitation.'],
];
const science=[
 ['Observing and asking questions','Describe observations and formulate a question that can be investigated.','Compare a dry leaf and a fresh leaf using sight and optional supervised touch. Separate what is observed from an explanation and draw a labelled comparison. No tasting unknown materials.','State two observations and one investigable question about leaves.','Colour and texture are observations; a question about change over time is investigable. An explanation is not itself an observation.'],
 ['Living and non-living things','Classify examples using more than movement alone.','Sort pictures of a plant, bird, stone and moving toy. Discuss growth and life processes and why a toy can move without being alive. Use pictures rather than captured animals.','Explain why movement alone cannot identify a living thing.','A moving toy is not alive; use several characteristics and age-appropriate explanations.'],
 ['Plant parts and their roles','Identify roots, stems and leaves and describe their broad roles.','Observe a pictured or safely potted plant without uprooting it. Draw roots, stem and leaves and connect each part to a function. Distinguish the observation from a function explanation.','Match roots, stem and leaves to one role each.','Roots take up water and anchor; stems support and transport; leaves make food by photosynthesis. Simplify language appropriately.'],
 ['Germination and fair comparisons','Plan an observation of seed germination while keeping a comparison fair.','Use teacher-handled safe seeds on damp paper and a comparison with different water availability. Keep seed type and location consistent; record changes over several days. Avoid mould handling and do not promise a fixed germination day.','Name the changed condition and one condition to keep the same.','Water availability is changed; seed type or location can remain the same. Seeds initially use stored food; light needs vary with species and stage.'],
 ['Materials and useful properties','Choose a material for a stated purpose using observed properties.','Compare paper, cloth and plastic in a hypothetical rain-cover task. Test small samples with clean water in trays, describing absorption and flexibility rather than assuming one material is best for every use.','Choose a cover material and justify with a test observation.','A water-resistant sample may suit the task; distinguish water resistance from other requirements such as strength and reuse.'],
 ['Solids, liquids and changes','Describe melting or evaporation without confusing the two.','Observe ice in a tray if available or use a teacher-prepared picture sequence. Compare water left in a shallow dish over time. No flames, boiling water or tasting.','Describe how melting differs from evaporation.','Melting changes solid to liquid; evaporation changes liquid to gas at the surface. The material has not simply disappeared.'],
 ['Separating a mixture','Select a separation method using the components’ properties.','Model separating dry large paper pieces from clean counters by sorting. Discuss a picture of filtering sand from water; only a teacher handles any demonstration and nobody drinks the water.','Can a simple filter remove dissolved salt? Explain.','No: dissolved salt passes through an ordinary filter with the water. Avoid claiming filtered demonstration water is safe to drink.'],
 ['Light and shadows','Explain how an opaque object can form a shadow.','Use a classroom torch and a card screen, never a laser or direct sunlight viewing. Move the object and record how the shadow changes while keeping other positions fixed.','What is needed to form the observed shadow?','A light source, an object blocking light and a surface receiving the shadow; do not direct lights into eyes.'],
 ['Forces and motion','Describe how a push or pull changes an object’s motion.','Roll a soft ball gently on a clear level surface, comparing starting and stopping. Keep learners clear of the path and use a tabletop picture alternative for mobility needs.','Describe one push and its observed effect.','Accept a change in speed or direction supported by observation; a force can also change shape.'],
 ['Energy in everyday situations','Identify an energy source and an observable effect.','Use pictures of a torch, moving bicycle and sunlight warming a surface. Trace a simple source-to-effect explanation without opening appliances or connecting electricity.','For a battery torch, name the source and one output.','The battery stores chemical energy; light and some heat are outputs. Use simpler wording with younger learners.'],
 ['Habitats and caring for surroundings','Explain a relationship between an organism and its habitat.','Observe school-ground pictures or conduct a supervised accessible walk. Note shelter, water and food evidence without disturbing nests or handling animals. Map one relationship and one protective action.','Explain how removing all plants could affect a small pictured habitat.','It could reduce food or shelter; require a stated relationship rather than claiming every organism responds identically.'],
 ['A small scientific investigation','Present a question, method, observations and a justified conclusion.','Revisit a safe materials or plant observation. Learners make a table, distinguish actual observations from predictions and explain a limitation. Do not invent results for an experiment that has not been carried out.','State one conclusion and one limit of the available evidence.','The conclusion must follow recorded observations; missing data and uncontrolled conditions are valid limitations.'],
];
const ghanaian=[
 ['Greetings and respectful responses','Use a context-appropriate greeting and respond politely in the chosen Ghanaian language.','The teacher models locally verified greetings for a peer and an older person. Partners role-play contexts and discuss differences in respectful usage without ranking languages or dialects.','Greet a peer and an adult role-play partner appropriately.','Check meaning, response and context against the locally verified model; accept valid dialect differences.'],
 ['Listening and following instructions','Follow spoken instructions and explain their order.','Give a short direction using familiar classroom objects in the selected language. Learners demonstrate, repeat meaning in their own words and exchange instructions.','Follow a direction then explain what was done.','Observe actual comprehension; exact repetition alone is insufficient evidence.'],
 ['Describing people and objects','Describe an imagined object using relevant locally verified vocabulary.','Use a bag or picture. Model its colour, purpose and one feature in the selected language. Partners describe objects for others to identify; avoid personal body judgments.','Give two details identifying a pictured object.','Details must match the picture and be understandable in the selected language; confirm spelling with the language’s accepted classroom reference.'],
 ['Sounds and the selected orthography','Relate a familiar spoken sound to an appropriate written form.','The teacher selects three verified words and sound-letter relationships from the chosen language’s approved material. Compare positions of sounds and practise building the words; do not impose English sound rules.','Read or build a word using the taught relationship.','Check against the chosen orthography and actual pronunciation; do not treat dialect variation as an automatic error.'],
 ['Reading a short local-language text','Retrieve a fact from a teacher-selected verified text.','Use a short classroom-appropriate passage in the chosen language. Model finding a fact in the text, then pairs ask and answer questions citing words or a sentence.','Identify a character or subject and one supported fact.','The answer must be supported by the selected passage; record the passage reference before classroom use.'],
 ['Retelling an original story','Retell a short original story in a logical order.','The teacher tells an original story about returning a borrowed book, using locally verified language. Learners sequence three pictures, retell and discuss a respectful response.','Retell the beginning, main event and ending.','Check sequence and understandable meaning, allowing more than one valid phrasing.'],
 ['Word meaning in context','Explain a familiar word using surrounding information.','Select a locally verified sentence in which context clarifies a word. Compare literal and context-appropriate interpretations without inventing proverbs or cultural meanings.','Explain the chosen word and identify a context clue.','Confirm the meaning with a reliable language reference or knowledgeable teacher; an unsupported literal translation is not enough.'],
 ['Constructing meaningful sentences','Build a sentence following the chosen language’s patterns.','Use verified word cards from the chosen language. Model a meaningful sentence, then change the actor or action. Compare the resulting meaning rather than forcing English word order.','Build and explain a new sentence with the taught pattern.','Check grammar and meaning in the selected language; teacher review of agreement and word order is required.'],
 ['Songs and oral literature','Discuss meaning and performance features of an authorized local-language piece.','Use a teacher-authored chant or a locally permitted short song. Discuss repetition, rhythm and meaning with voluntary participation and a spoken alternative. Avoid restricted or sacred material.','Explain one repeated feature and its effect.','Require a connection to the actual piece; acknowledge different interpretations supported by its context.'],
 ['Functional communication','Give a clear polite request in a familiar situation.','Role-play borrowing a classroom resource or asking for help in the selected language. For writing practice, use a fictional message and verify conventions before displaying it.','Make a request and respond appropriately.','Look for clear purpose, suitable register and a relevant response; do not send real messages.'],
 ['Planning and revising a short text','Improve a short original text in the selected language.','Plan a description or short narrative using pictures. The teacher checks spelling and grammar with a suitable reference; learners revise one unclear idea and explain the change.','Produce a short oral or written text and one justified revision.','Assess meaning, organization and locally verified language conventions separately.'],
 ['Language portfolio and sharing','Present selected language work and identify a learning goal.','Learners select a greeting, retelling and reading or writing example. Present through speech, audio-free role-play, drawing or text, then receive respectful feedback in the chosen language.','Explain one improvement and one next goal.','Use evidence from the learner’s work; do not claim this language-neutral plan supplies verified translations.'],
];
const history=[
 ['Past and present','Distinguish an account of the past from a present observation.','Compare teacher-created drawings of a classroom at two fictional times. Discuss what changed, what remained and what the pictures alone cannot establish.','Name one change and one question needing more evidence.','A visible change is supported; its cause may require another source.'],
 ['Ordering events','Arrange a short sequence and explain before and after.','Use an invented sequence: a school is planned, built, opened and later enlarged. Learners order cards and create a simple timeline without assigning fabricated real dates.','Place opening and enlargement on the timeline.','Opening precedes later enlargement in the stated story; avoid treating the invented example as local history.'],
 ['Objects as historical sources','Explain what an object might reveal and what remains uncertain.','Use a picture of an old exercise book or pot with known classroom permission. Distinguish description, possible use and unsupported ownership claims.','State one observation and one cautious inference.','An observation describes visible features; an inference needs justification and is not certainty.'],
 ['Oral accounts','Ask a respectful historical question and distinguish memory from confirmation.','Role-play an interview using an entirely fictional account of a school event. Compare two recollections and discuss why checking another source helps. No real interview or personal recording is required.','Write or ask a useful follow-up question.','Questions should be relevant and non-leading; memory can be valuable without being infallible.'],
 ['Written and visual records','Retrieve evidence from a dated record.','Create a fictional notice of a school exhibition with a date, place and purpose. Compare the notice with a picture caption and separate recorded details from assumptions.','What event and place are supported by the record?','Use only the provided record; a notice’s planned event is not proof it actually occurred.'],
 ['Communities and migration stories','Describe a movement story while acknowledging source limits.','Use an invented family moving between two unnamed communities for work. Map origin, destination and a stated reason; compare with another fictional reason without claiming a single story represents Ghana’s peoples.','Explain one reason for movement and one possible effect.','Reason must come from the account; effects are possibilities unless evidence is supplied.'],
 ['Work and exchange over time','Compare two ways of producing or exchanging goods.','Contrast fictional pictures of hand production and a later workshop. Discuss tools, labour and trade without assuming newer always means better.','Give one similarity and one difference.','Both can produce goods; differences must be visible or stated, not guessed from stereotypes.'],
 ['Leadership and community decisions','Describe how a decision can affect different people.','Use a fictional community deciding where to place a well. Give different characters’ needs and discuss leadership, consultation and the evidence needed for a fair account.','Explain two viewpoints in the story.','Recognize the stated interests; do not invent a universal customary rule for every Ghanaian community.'],
 ['Ghana’s historical landmarks','Use a verified source to place a national event in time.','The teacher provides a checked official or curriculum-approved source for Ghana’s independence. Learners connect the event, date and source, distinguishing a date from an explanation of its causes.','State the event date and identify the source used.','Ghana’s independence is dated 6 March 1957; verify the supplied source and avoid unsupported claims about all participants.'],
 ['Heritage and preservation','Explain a reason to preserve a historical place or object.','Use permitted pictures of a known heritage site with a checked caption. Discuss care, access and whose perspectives are represented; no unsupervised visits or handling of artifacts.','Suggest one preservation action and explain its purpose.','An action should protect the object or site without damaging it; local custodians’ guidance matters.'],
 ['Comparing historical accounts','Identify agreement, disagreement and missing evidence.','Provide two short fictional accounts of the same school exhibition, one by a visitor and one by an organizer. Learners compare emphasis and distinguish perspective from deliberate falsehood.','State one agreement and one question for further checking.','Use explicit evidence in the accounts and avoid assuming one perspective is complete.'],
 ['A small history display','Present a historical explanation with source labels.','Create an accessible display using fictional classroom records or teacher-verified local material. Label sources, order events and mark uncertain details rather than filling gaps with inventions.','Present one claim, supporting source and uncertainty.','Assess the link between evidence and claim; a polished display does not make an unsupported statement reliable.'],
];
const owop=[
 ['Knowing our classroom community','Identify ways people contribute to a shared space.','Use fictional classroom roles and pictures to discuss helping, listening and caring for materials. Learners draw a contribution without assuming everyone has identical needs.','Describe one helpful role and its effect.','The effect should be plausible and connected to the role, such as tidying keeping paths clear.'],
 ['Family and belonging','Describe caring relationships respectfully.','Discuss inclusive fictional household pictures. Learners identify care and shared tasks without being required to disclose their own home situation or rank family structures.','Identify one caring action in a picture.','Accept diverse caregivers and household structures; care is the focus.'],
 ['Needs and wants','Explain a basic distinction between a need and a want.','Sort fictional picture cards for safe water, food, shelter and optional treats. Discuss context and why some items may serve different needs for different people.','Explain one sorting choice.','Food and safe water meet basic needs; avoid judging a child’s circumstances or assuming one universal list of personal wants.'],
 ['Health and everyday cleanliness','Describe a practical clean-hands routine.','Use supervised handwashing pictures and a safe demonstration with soap and clean water. Sequence the routine and identify times such as before eating.','Order wet, soap/rub, rinse and dry cards.','Check sequence and actual safe practice; no claim that one routine prevents every illness.'],
 ['Directions and simple maps','Use a key and relative directions in a classroom map.','Draw an invented classroom plan with a door, shelf and reading area. Model a key and describe a route using beside, near and between before introducing compass directions if appropriate.','Give a route between two marked places.','The route should match the map and avoid obstacles; keep the map fictional rather than exposing home locations.'],
 ['Weather observations','Record weather observations without confusing them with long-term climate.','Observe the sky safely from shelter or use teacher-provided pictures. Record a symbol and describe what was observed rather than predicting certainty from one cloud.','Describe today’s observation and one suitable action.','Observation and practical action should match; do not view the sun directly or go outdoors in unsafe conditions.'],
 ['Water in our community','Identify water uses and ways to avoid waste.','Use pictures of washing, gardening and drinking. Discuss keeping storage covered and turning taps off; classroom activities use pictures or clean demonstration water, never unknown water tasting.','Suggest one water-saving action and its reason.','The action should reduce waste without compromising hygiene; appearance alone cannot establish drinking-water safety.'],
 ['Keeping surroundings clean','Plan a safe response to different kinds of litter.','Sort paper picture cards representing reusable materials, ordinary litter and hazardous items. Discuss adult reporting for sharps or unknown waste; no real waste handling.','What should a child do on seeing a broken glass picture scenario?','Stay clear and alert a responsible adult; do not pick it up.'],
 ['Work and community services','Explain a service and how people depend on it.','Role-play fictional interactions with a farmer, teacher or health worker using picture cards. Compare contributions without ranking occupations or providing medical advice.','Describe one service and who may benefit.','The explanation should connect the work to a real need and avoid stereotypes about gender or status.'],
 ['Ghana and shared symbols','Describe how a national symbol can represent belonging.','Use a teacher-checked picture of Ghana’s flag or coat of arms. Observe features and discuss respectful use without inventing meanings or requiring declarations of belief.','Describe a visible feature and identify where its explanation came from.','Keep observation separate from symbolic meaning; check meanings against a suitable official or approved source.'],
 ['Cooperation and fair decisions','Use listening and turn-taking to resolve a fictional problem.','Groups decide how to share a reading space with different needs. Practise explaining a reason, listening and revising a proposal rather than voting away someone’s safety or access.','Propose a fair arrangement and a reason.','Recognize participation and access needs; fairness may require different support rather than identical treatment.'],
 ['A community-care project plan','Plan a small achievable action and explain how to review it.','Design a fictional classroom book-care or water-saving reminder. Set a goal, safe roles and an observation that could show progress; no fundraising or external messages.','State the goal, one action and a check of progress.','The check should relate to the goal; acknowledge limits of a short observation.'],
];
const arts=[
 ['Observing lines and shapes','Use line and shape deliberately in an original image.','Observe permitted pictures or classroom objects. Try straight, curved and broken lines, then create an imagined scene and explain one choice.','Create an image using at least three kinds of line.','Look for intentional differences and an explanation; drawing realism is not the only measure of success.'],
 ['Colour and visual mood','Choose colours to communicate an idea and explain the choice.','Compare original paper designs with contrasting colours. Use crayons or safe school paint, then discuss how personal associations differ rather than declaring universal colour meanings.','Make two small designs with different moods.','Accept justified personal choices; do not treat one cultural association as universal.'],
 ['Texture and pattern','Create a repeating design using safe materials.','Make rubbings from clean large textured surfaces or use paper textures. Plan a repeating unit and compare regular repetition with random placement.','Create and identify a repeating unit.','The unit should repeat consistently; avoid sharp objects or collecting unknown substances.'],
 ['Composition and space','Arrange elements to guide attention.','Compare two layouts of the same original cut-paper shapes. Discuss foreground, background and spacing, then compose a scene with a clear focus.','Explain which element attracts attention and why.','Position, size, contrast or spacing may support the explanation; there is no single required composition.'],
 ['Making a paper collage','Combine materials to express a theme.','Use clean paper offcuts and child-safe adhesive to create a caring-for-books collage. Plan, arrange without glue, then attach and revise.','Produce a collage and explain one material choice.','Check intentional selection, safe use and relation to the theme, not cost of materials.'],
 ['Designing a useful object','Develop a simple design for a stated classroom need.','Sketch a paper bookmark for a fictional reading corner. Compare readability, durability and material use before making a safe paper prototype.','Present a prototype and one design improvement.','The improvement should address the stated use; decoration alone may not solve a functional problem.'],
 ['Pulse and rhythm','Distinguish a steady pulse from a changing rhythmic pattern.','Tap a comfortable steady pulse on the desk or clap softly. Add an original short rhythm and compare. Offer visual beat cards and silent movement alternatives.','Maintain a pulse while describing a separate rhythm.','Pulse is the regular underlying beat; rhythm is the pattern of durations. Avoid excessive sound levels.'],
 ['Voice and original song','Perform an original short chant with clear phrasing.','Create a teacher-authored chant about caring for shared books. Explore loud/soft and fast/slow within comfortable voice use; participation may be spoken, visual or instrumental.','Perform or represent a phrase and explain a choice.','Assess purposeful expression and safe voice use; no copyrighted song reproduction is needed.'],
 ['Movement and expression','Use accessible movement to communicate an idea.','Groups represent opening a book, curiosity and discovery through controlled movement or seated gestures. Establish clear space and consent; no lifts or risky acrobatics.','Show a short movement sequence with a beginning and end.','Look for a coherent expressive sequence, safe spacing and an accessible participation route.'],
 ['Drama and character','Develop a character’s choice in a fictional situation.','Role-play a borrowed book returned damaged. Plan character goals, a respectful response and an alternative ending, avoiding personal disclosures.','Present a short scene and explain a character decision.','Decisions should fit the scene; distinguish portraying a viewpoint from endorsing it.'],
 ['Responding to creative work','Give specific respectful feedback using visible evidence.','View original class designs with permission. Use I notice and I wonder prompts before suggesting a change connected to the creator’s purpose.','Give one evidence-based comment and one useful suggestion.','Feedback should refer to the work rather than the creator’s identity or personal worth.'],
 ['A small creative exhibition','Present an original work and explain its development.','Select visual, musical, movement or drama work from the unit. Prepare a short artist’s statement, an accessible display and a revision based on feedback.','Explain purpose, process and one revision.','Assess intentional process and reflection; do not claim copied traditional motifs or performances are unrestricted.'],
];
const rme=[
 ['Respect and different beliefs','Listen respectfully and distinguish learning about belief from required observance.','Use fictional characters with different religious or non-religious family backgrounds. Agree on respectful discussion and allow learners to pass on personal questions.','Describe a respectful response to a different belief.','Listening and asking a non-mocking question are suitable; no pupil must disclose or affirm a belief.'],
 ['Honesty and consequences','Explain how honesty affects trust in a fictional situation.','Discuss a learner who finds a borrowed book torn. Compare hiding damage with reporting it and helping arrange repair; consider consequences for several people.','Give a reason for a truthful response.','Connect the response to trust and responsibility without labelling a child’s whole character.'],
 ['Care and compassion','Identify an action that responds to another person’s stated need.','Use a fictional classmate who needs a quieter reading place. Groups propose help, ask what support is wanted and avoid assuming every person needs the same thing.','Explain one compassionate action and how consent matters.','The action should support the person’s actual need rather than impose unwanted help.'],
 ['Responsibility for shared things','Explain a fair way to care for common resources.','Plan a class book-borrowing routine. Discuss reasonable responsibilities, accessible records and how to respond when mistakes occur.','Suggest a responsibility and a fair response to accidental damage.','Responses should be proportionate, respectful and aimed at repair, not humiliation.'],
 ['Cooperation and service','Plan a safe action benefiting a group.','Use a fictional book-sorting project with varied accessible roles. Learners explain how working together differs from one person doing everything.','Name a role and how it contributes.','Recognize meaningful contributions through speaking, drawing, organizing or other accessible methods.'],
 ['Religious celebrations as community practices','Compare selected public features of celebrations respectfully.','Use teacher-verified approved descriptions of a Christian, Muslim or Ghanaian traditional celebration, where appropriate. Discuss gathering, sharing and meaning without staging worship or claiming all families practise identically.','Identify one similarity and one source-supported difference.','Answers must reflect the provided sources; participation in a religious act is not an assessment requirement.'],
 ['Stories and moral reasoning','Explain a lesson drawn from an original ethical story.','Tell an original story about returning a lost pencil. Compare possible choices and their consequences; separate understanding a moral question from memorizing one slogan.','Give a justified alternative action for the character.','Several responses may be defensible if they respect others and address the situation.'],
 ['Peaceful disagreement','Practise a respectful way to express disagreement.','Role-play a dispute about a shared drawing tool. Model stating the issue, hearing both accounts and proposing a fair turn without threats.','Demonstrate a respectful sentence and a next step.','Look for listening and a workable arrangement; seek adult help for unsafe situations rather than requiring children to mediate harm.'],
 ['Care for the environment','Connect a value with a practical safe action.','Discuss keeping a shared reading area clean through fictional picture cards. Compare reducing waste, reuse and asking adults to handle hazards.','Explain one environmental action and its reason.','An action should be safe and achievable; no handling of sharps, chemicals or unknown waste.'],
 ['Fairness and inclusion','Explain why fair treatment may include different support.','Compare giving everyone the same tiny-print book with offering large print or oral access where needed. Discuss access without asking learners to identify disabilities.','Suggest a more inclusive arrangement.','Fairness considers barriers and dignity; equal access does not always mean identical materials.'],
 ['Reflecting on a decision','Use reasons and consequences to review an ethical choice.','Revisit a fictional character who excluded someone from a group. Learners identify affected people, possible repair and a more inclusive next action.','Explain one consequence and a constructive repair.','The repair should address the harm without forced personal confessions or public shaming.'],
 ['A values-in-action portfolio','Present a reasoned proposal reflecting a shared value.','Create a fictional plan for caring for class materials with clear roles, access and a way to review fairness. Link actions to honesty, care or responsibility without requiring religious assent.','Explain a value, an action and a reason.','Assess reasoning and respect, not conformity to a particular religion or family practice.'],
];
const pe=[
 ['Safe space and controlled movement','Move or gesture with awareness of space and an agreed stop signal.','Check a clear level area and offer seated or low-movement options. Practise starting, stopping and changing direction at a comfortable pace; no racing or contact.','Respond to a stop signal while maintaining space.','Observe control and awareness, not speed; stop activity if the learner reports discomfort.'],
 ['Balance and body control','Maintain a comfortable stable position with support if needed.','Model a wide stable stance or seated balance. Learners explore supported positions near a stable surface, choosing an accessible challenge without closed-eye balance or elevated equipment.','Show a stable position and explain one safety choice.','Accept different support needs; a safe controlled posture meets the goal.'],
 ['Locomotor movement patterns','Combine accessible travelling actions in a short sequence.','Use walking, stepping, wheeling or seated arm travel patterns along a clear route. Model direction changes and allow self-selected comfortable intensity.','Perform or describe a three-action sequence.','Check controlled order and safe spacing; do not assess everyone against one movement method.'],
 ['Throwing and receiving softly','Send and receive a soft object using controlled force.','Use a large soft ball or rolled cloth at short distance. Practise rolling first, then an optional gentle toss with willing partners and clear space.','Roll an object towards a target or partner safely.','Control and appropriate force matter; no hard balls or throws at faces.'],
 ['Aiming at a target','Adjust a controlled action using feedback.','Roll a soft object towards a large floor target. Learners choose a suitable distance, observe the result and change one aspect of the next attempt.','Describe one adjustment and its effect.','Look for a connection between action and result rather than a single performance threshold.'],
 ['Rhythm and coordination','Coordinate an accessible movement with a steady beat.','Use soft claps or visual beat cards. Create a short sequence of taps, steps or seated gestures and practise at a comfortable pace.','Follow a four-beat pattern and explain the repeat.','Offer visual and silent alternatives; avoid loud sound or forced synchronization.'],
 ['Simple non-contact games','Apply a rule and share turns in an inclusive game.','Create a rolling-to-target game with adjustable distance and roles. Explain stop rules, no-contact boundaries and how different supports preserve participation.','State one rule and demonstrate fair turn-taking.','Rules should support safety and access; winning is not the only measure of learning.'],
 ['Warm-up and recovery routines','Describe how to start and finish activity gradually.','Model gentle comfortable movement before a simple task and a gradual slowdown afterward. Discuss noticing breathing and comfort without prescribing individual training or stretches.','Describe one gradual start and finish action.','Avoid forced stretches, pain or competitive endurance; adapt to school guidance and individual needs.'],
 ['Hydration and safe participation','Recognize when to pause and seek adult help.','Use fictional scenarios involving heat, thirst or discomfort. Discuss breaks, shade and telling the teacher; keep water available according to school practice.','What should a learner do if an activity causes pain or dizziness?','Stop, tell a responsible adult and follow school response procedures; do not encourage pushing through symptoms.'],
 ['Cooperation and communication','Use a clear signal to coordinate a group task.','Groups move a soft object between floor targets through rolling or an accessible alternative. Plan roles and signals without lifting people or heavy objects.','Explain how a signal helped the group.','Check clarity, consent and inclusion rather than raw speed.'],
 ['Designing an inclusive game','Adapt one rule or resource to remove a participation barrier.','Review the target game and alter target size, distance or response method. Learners explain how the adaptation keeps the challenge meaningful.','Propose an adaptation and test it safely.','An adaptation should improve access without isolating or embarrassing a learner.'],
 ['Movement reflection and demonstration','Demonstrate a chosen skill and reflect on safe improvement.','Learners select rolling, controlled movement or a rhythm pattern. Use self-comparison, a comfortable demonstration and supportive feedback; no public fitness ranking.','Describe one improvement and one safe next step.','Assess control, reflection and participation using accessible evidence, not comparison of bodies or abilities.'],
];
const computing=[
 ['Digital and non-digital tools','Explain a tool’s purpose and distinguish a digital example.','Compare pictures of a notebook, calculator and computer. Discuss input, output and purpose without assuming every electronic object has the same capabilities.','Name a tool and explain what it helps a user do.','A valid explanation links a tool to a task; a paper notebook remains useful without being digital.'],
 ['Input, processing and output','Describe a simple information flow.','Role-play entering a sum, following a rule and displaying a result. Use paper cards first; a device demonstration is optional and teacher-controlled.','For a typed name displayed on a screen, identify input and output.','Typing supplies input; displayed text is output. Processing links them.'],
 ['Care and ergonomics','Identify a safe respectful way to use shared equipment.','Use pictures to discuss dry hands, clear cables and comfortable supported positioning. No pupil handles electrical plugs, damaged equipment or mains connections.','What should happen if a cable looks damaged?','Stop using the equipment and tell the responsible adult; do not repair or test it.'],
 ['Keyboard and text entry','Enter or arrange text accurately using relevant controls.','Use a paper keyboard or an offline teacher-controlled editor with fictional text: Our class reads. Model space, backspace and enter without opening accounts.','Correct Ourclass reeds. to the model sentence.','Our class reads. Check spacing and the intended word; offer alternative input methods.'],
 ['Files and meaningful names','Organize fictional files using names and folders.','Sort paper file cards into Reading and Pictures folders. Compare clear names with vague ones; optional offline demonstration must use disposable fixture files only.','Choose a clear name for an imagined reading poster file.','A name such as reading-poster-v1 is meaningful; do not rename or delete real user files.'],
 ['Creating a simple document','Organize a document with a title and readable content.','Plan a classroom reading notice on paper or in an offline disposable document. Choose a heading, short message and spacing without inserting personal data.','Explain two layout choices that improve readability.','Heading hierarchy and sensible spacing are suitable; decoration should not obscure content.'],
 ['Algorithms as instructions','Write an ordered sequence with a clear starting state.','Give paper instructions for moving a token across a drawn grid. A partner follows literally and identifies missing or ambiguous steps.','Write a sequence moving two squares right then one up.','The sequence must define the start, order and intended directions; no actual software is required.'],
 ['Patterns, repetition and debugging','Find and correct an error in a simple repeated instruction.','Use a paper pattern intended as clap-tap repeated three times. Present one incorrect step, trace the sequence and repair it. Introduce a repeat instruction after the pattern is understood.','Explain the error and give a corrected instruction.','A valid correction produces the intended sequence and explains why the original failed.'],
 ['Information and source checking','Distinguish a claim from evidence supporting it.','Use two fictional printed web-page cards about a class event, one with author/date and supporting record. Discuss why appearance alone does not prove accuracy; no browsing is required.','Name two checks before trusting a claim.','Check source, date, supporting evidence and corroboration; a professional-looking page can still be wrong.'],
 ['Privacy and personal information','Recognize information that should not be shared in a public example.','Sort fictional cards such as favourite colour, password and home address. Explain context and adult guidance without asking for real details. No accounts or messages are created.','Should a classroom poster include a real password? Explain.','No; passwords are private credentials. Use invented examples only.'],
 ['Respectful digital communication','Draft a clear respectful message without sending it.','Create a fictional message requesting a book-return reminder. Discuss tone, recipient and avoiding unnecessary personal information; use paper or a disposable offline text.','Improve a rude fictional message while preserving its purpose.','Check respectful wording and clear request; do not send the message or enter real contacts.'],
 ['A paper-first digital project','Present a useful information design and explain its logic.','Plan a fictional reading notice or a grid-navigation algorithm. Include audience, steps, a test and a revision. Device use is optional; no installs, logins or changes to real files.','Explain the design, one test and one revision.','The revision should respond to an observed issue; assess reasoning separately from device access.'],
];
const french=[
 ['Greeting and responding','Exchange a short polite French greeting.','Model Bonjour. and Au revoir. with context pictures. Partners practise greeting and parting, then discuss when Salut is informal. Instructions remain accessible in a familiar classroom language.','Greet a teacher role-play partner politely.','Bonjour is suitable; support pronunciation without treating accent variation as failure.'],
 ['Introducing oneself','State a fictional name using a simple French model.','Use Je m’appelle Ama. and Comment tu t’appelles ? with invented character cards. Learners exchange names without being required to share personal details.','Introduce an invented character using Je m’appelle.','Je m’appelle followed by the intended name communicates the model; evaluate meaning before accuracy detail.'],
 ['Asking how someone is','Give a simple response about a fictional character’s wellbeing.','Model Ça va ? and Ça va bien, merci. Use picture characters and allow a neutral response; do not pressure learners to disclose feelings.','Complete a short greeting dialogue.','A relevant greeting, question and response meet the communicative aim.'],
 ['Numbers in simple exchanges','Recognize and use French numbers one to ten.','Use un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix with large picture groups. Connect spoken forms to quantities, then practise a pretend request.','Match trois, cinq and huit to quantities.','3, 5 and 8 respectively.'],
 ['Classroom objects','Name familiar pictured objects with a taught article.','Introduce un livre, un stylo and une table using pictures. Model C’est un livre. Partners identify an object from a small set and check the article with the model.','Identify a pictured book in a short sentence.','C’est un livre. Avoid inferring grammatical gender from an object’s appearance.'],
 ['Colours in descriptions','Recognize a small set of colour words in context.','Teach rouge, bleu, vert and jaune using cards. Use the fixed examples un livre rouge and un stylo bleu; discuss that agreement depends on the noun and needs checking for new examples.','Match rouge and jaune to colour cards.','Red and yellow. Do not generalize an unverified adjective ending to every noun.'],
 ['Likes and dislikes','Express a simple preference using a model.','Model J’aime lire. and Je n’aime pas courir. with fictional characters. Learners choose from verified phrase cards and ask a partner to identify the meaning.','Express an invented character’s liking for reading.','J’aime lire. The activity should assess the phrase, not whether the learner shares the preference.'],
 ['Where an object is','Use a simple location phrase with pictures.','Model Le livre est sur la table. and Le stylo est sous la table. Move picture objects and compare sur and sous.','Describe a book shown under a table.','Le livre est sous la table.'],
 ['Polite requests','Make a simple polite request in a role-play.','Model Un livre, s’il vous plaît. followed by Merci. Use pretend classroom resources; explain the polite vous form without requiring contact outside class.','Request a book politely and thank the partner.','Un livre, s’il vous plaît. Merci. Accept another verified polite equivalent.'],
 ['Reading a short French text','Retrieve meaning from a short model text.','Read: Je m’appelle Ama. J’aime lire. J’ai un livre rouge. Learners match each sentence to a picture and distinguish name, preference and possession.','What does the character like doing? What colour is the book?','Reading; red. Check comprehension independently of pronunciation.'],
 ['Writing a short introduction','Create a short text using verified sentence models.','Use fictional names and taught phrases to build a two- or three-sentence introduction. Peer-check against the models; verify any additional vocabulary before including it.','Write an invented introduction including a name and a preference.','For example Je m’appelle Kofi. J’aime lire. Check sentence boundaries and meaning.'],
 ['A French communication showcase','Sustain a short prepared exchange and explain its meaning.','Pairs combine greeting, fictional introduction, object request and thanks. Offer written or picture-supported alternatives and review one improvement after feedback.','Perform or write a short coherent exchange.','Check communicative sequence and taught phrases. This is a beginner communication unit, not full grade-specific French coverage.'],
];
const arabic=[
 ['Greetings and meaning','Recognize and exchange a short Arabic greeting.','Model مرحبًا (marḥaban, hello) using a teacher-verified pronunciation. Match the greeting to a picture context and practise a neutral response without requiring religious observance.','Identify the greeting and its purpose.','It is a greeting meaning hello; transliteration is a support, not a substitute for checked pronunciation.'],
 ['Right-to-left print awareness','Identify the reading direction of a short Arabic word.','Show كتاب (kitāb, book). Model tracking right to left and distinguish overall reading direction from the behavior of embedded numbers or other scripts.','Show where to begin reading the Arabic word.','Begin on the right; do not reverse the individual letter forms to imitate reading direction.'],
 ['Letters and changing forms','Notice that a letter’s shape can depend on its position.','Use teacher-verified cards for ب and a short word containing it, such as باب (bāb, door). Compare forms visually without claiming every Arabic letter joins on both sides.','Find ب in the provided word or card set.','Use the verified written model; Arabic letters do not all connect in the same way.'],
 ['Sound and vocabulary matching','Match a taught spoken word to a pictured meaning.','Teach كتاب (book), قلم (qalam, pen) and باب (door) with a qualified pronunciation model. Learners match word cards to pictures and ask for repetition when needed.','Match قلم and باب to pictures.','Pen and door respectively; pronunciation should be checked by the teacher.'],
 ['Introducing a fictional name','Use a short model to introduce an invented identity.','Model اسمي آما (ismī Āmā, my name is Ama). Discuss that rendering unfamiliar names should be checked rather than guessed. Practise with teacher-verified name cards.','Explain the meaning of اسمي and use a verified model.','اسمي means my name is; verify any added name spelling before classroom use.'],
 ['Simple numbers','Recognize taught Arabic number words for one to five.','Use واحد، اثنان، ثلاثة، أربعة، خمسة with quantity pictures and a teacher-verified spoken model. Treat number agreement in longer noun phrases as a separate topic requiring verification.','Match ثلاثة and خمسة to quantities.','Three and five. Avoid constructing unchecked noun-number phrases.'],
 ['A basic object statement','Understand a simple demonstrated Arabic sentence.','Model هذا كتاب (hādhā kitāb, this is a book) with a picture. Compare the whole model with a word-only label and practise using the taught masculine noun example.','Explain the sentence هذا كتاب.','This is a book. Do not generalize هذا to all nouns without teaching the appropriate demonstrative.'],
 ['Listening for familiar words','Identify a known word in a short verified spoken model.','The teacher reads taught vocabulary in a shuffled order. Learners point to matching pictures, then explain which visual and sound clues helped. No recording of pupils is needed.','Identify a spoken instance of كتاب from three picture choices.','The book picture matches; distinguish listening recognition from independent reading.'],
 ['Polite communication','Use a short polite Arabic expression in context.','Model شكرًا (shukran, thank you) and من فضلك (min faḍlik, please) using a checked pronunciation and context. Discuss variations of address before extending the model.','Choose an expression for thanking someone.','شكرًا is appropriate; address-dependent forms need teacher verification for new examples.'],
 ['Reading a short taught text','Retrieve meaning from connected taught models.','Use the short text هذا كتاب. اسمي آما. Match each sentence to its meaning and track the Arabic text correctly. Keep unfamiliar vocabulary out of the assessment.','Which sentence identifies an object?','هذا كتاب identifies a book; the other sentence gives a name.'],
 ['Writing and reviewing a model','Reproduce or assemble a taught Arabic model accurately.','Use large verified cards to assemble هذا كتاب, then practise copying with correct direction and letter connections. Offer arranging cards as an alternative to handwriting.','Assemble or copy the taught sentence and explain its meaning.','Compare spacing, direction and forms with the verified model; assess meaning separately from fine-motor control.'],
 ['Arabic learning portfolio','Present taught words and a short exchange with checked meaning.','Learners select greeting, vocabulary and a simple sentence from the unit. The teacher verifies script and pronunciation before presentation; learners note one area for further practice.','Present three taught items and explain their meanings.','This is a beginner Arabic literacy and communication unit, not a claim of complete JHS Arabic coverage or independently verified pronunciation.'],
];
const social=[
 ['Identity and belonging','Explain how people can belong to more than one community.','Use fictional profiles with language, school and local interests. Discuss shared and different identities without requiring personal or sensitive disclosures.','Explain two forms of belonging for a fictional character.','Answers should follow the profile and avoid stereotypes or assumptions about all members of a group.'],
 ['Culture and respectful inquiry','Distinguish a cultural observation from a generalization.','Compare teacher-verified descriptions of public practices from two contexts. Discuss within-group variation and ask respectful questions without reenacting restricted practices.','Revise a statement beginning Everyone from this group always...','A stronger statement identifies a specific source/context and acknowledges variation.'],
 ['Maps and interpreting space','Use a map key, scale and direction to explain a route.','Work with a fictional settlement map. Identify services, a key and an accessible route; older learners compare routes using a stated scale.','Describe a route and one reason for choosing it.','The route must match the map and stated constraints; do not publish learners’ home locations.'],
 ['Population and services','Explain a relationship between population patterns and service needs.','Use fictional settlement counts and service locations. Compare access without claiming real current population figures; distinguish totals from per-person measures.','Suggest one service priority and evidence for it.','A priority should follow the supplied scenario and acknowledge missing information such as travel distance or capacity.'],
 ['Environment and resource use','Analyze a trade-off in a resource-use decision.','A fictional community considers clearing a shaded area for a market. Groups identify possible benefits, environmental costs and alternatives using a stakeholder table.','State a benefit, cost and possible alternative.','Recognize uncertainty and multiple interests; do not present one option as cost-free.'],
 ['Citizenship and shared responsibilities','Explain participation and responsibility in a fictional public decision.','Role-play a school-community meeting about access to a reading space. Separate listening, evidence and respectful participation from obedience to every suggestion.','Describe a responsible way to contribute.','A reasoned contribution respects others and the agreed process; no partisan campaigning or real political contact is required.'],
 ['Rights, inclusion and access','Identify an access barrier and a practical response.','Use a fictional service with steps, tiny-print notices and one language. Learners propose accessible communication and physical alternatives without asking classmates to disclose disabilities.','Name a barrier and a response that addresses it.','The response must match the barrier and preserve dignity; refer legal specifics to verified teaching sources.'],
 ['Work and responsible consumption','Explain how purchasing decisions involve costs and constraints.','Compare fictional durable and disposable classroom resources. Discuss price, repair, availability and waste rather than assuming the cheapest purchase is always best.','Justify a choice and state an assumption.','A defensible choice links evidence to the scenario and acknowledges trade-offs.'],
 ['Conflict and peaceful problem solving','Compare ways of responding to a disagreement.','Use a fictional dispute over a shared space. Learners identify interests, propose a safe discussion process and recognize situations requiring adult help.','Explain a constructive next step and why it is suitable.','Listen and clarify interests where safe; do not require children to mediate threats, abuse or dangerous conflict.'],
 ['Information and public claims','Evaluate a claim using source, date and evidence.','Provide two fictional printed notices about a community project, one with an unsupported statistic. Learners identify what can be checked and how uncertainty should be reported.','Name one claim needing corroboration and a suitable source type.','A relevant independent record or direct observation may help; repetition alone is not corroboration.'],
 ['Planning a community study','Design an ethical, limited inquiry without collecting sensitive data.','Plan a classroom-only study of a fictional waste-reduction proposal using supplied data. Define a question, method, limitations and how to avoid identifying individuals.','State a question and what evidence would answer it.','The proposed evidence should be relevant and proportionate; no real interviews, personal data or external messages are needed.'],
 ['A reasoned community proposal','Present a proposal supported by evidence and an honest limitation.','Groups use a fictional case to propose an accessible reading area or resource-care plan. Include stakeholders, evidence, trade-offs and a way to review results.','Explain a recommendation, its support and one limitation.','Assess evidence-to-claim reasoning, fairness and realistic scope rather than agreement with one preferred policy.'],
];
const career=[
 ['Needs and design problems','State a user need before proposing a product.','Use a fictional reading corner needing bookmarks and clear shelf labels. Interview a role-play user, list constraints and distinguish need from decoration.','Write a one-sentence design problem and a success criterion.','A criterion should be observable, such as readable labelling, and relevant to the user.'],
 ['Materials and selection','Choose a material using a justified property.','Compare clean card, paper and fabric offcuts for a bookmark prototype. Discuss strength, flexibility, reuse and availability without claiming one best material for all products.','Justify a material choice and one trade-off.','The reason should connect a property with intended use and acknowledge a constraint.'],
 ['Tools and safe working','Identify appropriate safe tools for a paper prototype.','Use pictures and optional child-safe scissors under school supervision. Plan a clear workspace, safe storage and an alternative using pre-cut pieces. No blades, power tools, flames or hot glue.','Explain one safe-use rule and its purpose.','Check the specific hazard and control; never assess willingness to use unsafe equipment.'],
 ['Sketching ideas','Communicate a design through labelled sketches.','Draw two original shelf-label or bookmark designs. Add dimensions in a consistent unit and labels for materials and intended users.','Produce a sketch that another person can interpret.','Look for useful labels and clear features rather than artistic realism alone.'],
 ['Measuring and marking','Use consistent units to mark a simple paper pattern.','Prepare a 5 cm by 15 cm paper bookmark pattern with a ruler or a pre-marked alternative. Check from zero and compare tolerances before cutting.','Explain how to check a marked length.','Align the zero mark and read the intended unit; do not confuse the ruler’s edge with zero.'],
 ['Making a prototype','Follow a safe planned sequence to produce a paper model.','Use clean paper/card, child-safe adhesive and optional pre-cut pieces. Make a bookmark or shelf label, pausing to compare the result with the sketch.','Show one construction step and explain its order.','The step should support accuracy or safety; a prototype is a test model, not proof of production quality.'],
 ['Joining and finishing','Choose a suitable safe way to join or finish materials.','Compare folded tabs and a small amount of school-safe glue using paper samples. Discuss drying, excess adhesive and whether a join meets its purpose.','Select a join for a paper label and justify it.','Judge the tested sample and intended use; avoid unsupported claims about every adhesive or material.'],
 ['Testing a design','Evaluate a prototype against stated criteria.','Test readability from an agreed classroom distance and whether a bookmark fits a fictional book size. Record actual observations, not invented praise.','Report one criterion, test and observed result.','The test must relate to the criterion; record failure honestly as information for redesign.'],
 ['Improving a prototype','Revise a feature in response to test evidence.','Use the previous test to change contrast, size, material use or join. Compare before and after under the same conditions where possible.','Explain a revision and the evidence motivating it.','A revision should address an observed issue rather than merely add decoration.'],
 ['Resources and fictional costing','Estimate simple material costs and state assumptions.','Use invented prices: a card sheet costs GH₵2 and yields four bookmarks. Exclude real purchasing and distinguish material cost from all business costs.','Find material cost per bookmark under the stated assumption.','GH₵0.50; this excludes labour, wastage and other costs.'],
 ['Communicating a product responsibly','Explain features without making unsupported claims.','Write a fictional product card for the prototype with purpose, materials and a tested feature. Avoid claiming waterproof, guaranteed or environmentally harmless without evidence.','Replace one exaggerated claim with a supported description.','A precise tested description is stronger than an unverified absolute claim.'],
 ['Design portfolio and reflection','Present a design process from need through revision.','Organize sketches, criteria, test notes and a final paper prototype. Explain a constraint, one useful failure and a next test; no real selling or payments occur.','Present the need, design, test and revision.','Assess process and evidence, safe practice and reflection rather than appearance or material cost alone.'],
];
