 'physical-education':{title:'Movement, cooperation and wellbeing',strand:'Movement and safe participation',rows:pe,resources:'Clear accessible space, soft rolled cloth or ball, large targets, visual signals and picture alternatives.',local:'Adapt all movement to school safety procedures, the available space and individual access needs. Offer non-contact and seated alternatives; no medical assessment or fitness ranking is provided.'},
 'computing':{title:'Digital thinking and safe information use',strand:'Digital literacy and computational thinking',rows:computing,resources:'Paper keyboards, fictional file/message cards and grid maps; optional teacher-controlled offline equipment only.',local:'All activities can run on paper. Do not install software, open accounts, send messages or alter real files during these lessons.'},
 'french-language':{title:'Everyday communication',strand:'Oral communication, reading and writing',rows:french,resources:'Verified French phrase cards, picture objects, quantity cards and a teacher pronunciation model.',local:'This is a beginner communication unit with class-level practice targets, not a complete grade-specific language course. Verify pronunciation and additional vocabulary before use.'},
 'arabic':{title:'Beginning literacy and communication',strand:'Oral language and Arabic print',rows:arabic,resources:'Large verified Arabic word cards, matching pictures and a qualified teacher pronunciation model.',local:'Verify Arabic script rendering and pronunciation before use. Transliteration is only a support. This beginner unit is not a full grade-specific Arabic course.'},
 'social-studies':{title:'Community enquiry and responsible decisions',strand:'Social enquiry and community life',rows:social,resources:'Fictional case studies, accessible maps, supplied data and teacher-verified reference descriptions.'},
 'career-technology':{title:'Safe design and paper prototypes',strand:'Design, making and evaluation',rows:career,resources:'Clean card, paper, ruler, school-safe adhesive and optional supervised child-safe scissors or pre-cut pieces.',local:'Paper prototypes only. No blades, flames, hot glue, power tools, real purchases or selling are required.'},
