const aliases={'creative-arts-and-design':'creative-arts','physical-education-and-health':'physical-education'};
const stages={lower:[
 {name:'Supported demonstration',goal:'Show the skill with pictures, concrete examples or an oral response.',practice:'Use two clear choices, model one response, then invite a short independent attempt. Accept drawing, pointing or a familiar classroom language before extending English wording.',check:'Record whether the learner can demonstrate the idea after a model.'},
 {name:'Explain and compare',goal:'Explain the choice and compare two examples.',practice:'Model one example, then ask pairs to compare a second case and explain a difference. Invite a complete oral sentence or a labelled drawing.',check:'Require an explanation linked to the example, not only a selected answer.'},
 {name:'Apply and explain',goal:'Apply the idea to a new example and explain a reason.',practice:'After guided practice, offer a new picture or short scenario. Ask learners to explain their response and identify one possible mistake.',check:'Look for transfer to the new example and a relevant reason.'},
 ],upper:[
 {name:'Describe with evidence',goal:'Organize a response and cite a relevant detail.',practice:'Model a labelled or short written response. Give a new case and require a detail from the provided material to support the answer.',check:'Check the link between the response and the source or observation.'},
 {name:'Compare and justify',goal:'Compare two responses and justify an improvement.',practice:'Pairs compare two examples using an agreed criterion, then each learner independently revises a response and explains the change.',check:'Require a justified comparison and a visible revision.'},
 {name:'Apply and evaluate',goal:'Apply the idea to an unfamiliar case and evaluate a limitation.',practice:'Use an unfamiliar but accessible scenario. Learners plan an independent response, evaluate it against a criterion and state one limitation or next question.',check:'Look for independent application, a relevant criterion and a realistic limitation.'},
 ],jhs:[
 {name:'Analyze and support',goal:'Explain a relationship using relevant evidence.',practice:'Model how to separate a claim from its support. Give a second scenario for pair analysis, followed by an independent explanation with evidence.',check:'Distinguish a supported statement from an assumption.'},
 {name:'Compare and evaluate',goal:'Compare alternatives using explicit criteria and evidence.',practice:'Learners analyze two approaches, state a criterion and justify a choice. Ask for a counterexample or condition that could change the conclusion.',check:'Require reasoning about an alternative and the limits of the chosen approach.'},
 {name:'Synthesize and defend',goal:'Develop a reasoned response and defend it while acknowledging limitations.',practice:'Learners synthesize the unit idea in a small independent product, critique an alternative and revise after a question. Require an honest statement of uncertainty.',check:'Assess synthesis, responsiveness to feedback and a justified limitation.'},
 ]};
const practiceFamilies={
 language:[
  {name:'Supported communication',goal:'Recognize the taught meaning and produce a supported response.',practice:'Model the taught language slowly with a verified picture or phrase card. Learners match meaning, rehearse a response and then try once with reduced prompting. Check pronunciation and script against the teacher’s verified model.',check:'Record comprehension and the amount of prompting separately from pronunciation or handwriting.'},
  {name:'Adapt a short exchange',goal:'Use a taught model in a second relevant context.',practice:'After modelling, change the pictured person, object or situation using only verified vocabulary. Pairs exchange roles, explain meaning and compare a response with the taught model.',check:'Check whether the learner adapts the phrase meaningfully, not simply repeats it without understanding.'},
  {name:'Independent use and revision',goal:'Build a short original response from verified taught language and revise it.',practice:'Learners combine taught words or sentence models for a new picture or role-play, explain their meaning and improve one feature after feedback. Verify any new vocabulary, grammar or script before using it.',check:'Look for an understandable independent response and a specific improvement against the verified model.'},
 ],
 movement:[
  {name:'Controlled participation',goal:'Demonstrate a safe accessible version of the movement or decision.',practice:'Model a comfortable option and a seated or low-movement alternative. Learners choose an appropriate challenge, practise with clear space and describe one control or safety cue.',check:'Assess safe control and the explanation rather than speed, strength or a fixed body position.'},
  {name:'Observe and adapt',goal:'Use feedback to adapt a safe action or participation rule.',practice:'After a short voluntary attempt, learners describe what helped and choose one safe adjustment to distance, target, pace or communication. Compare the experience without ranking bodies or abilities.',check:'Look for a relevant safe adjustment and a reflection on its effect.'},
  {name:'Plan inclusive participation',goal:'Explain and demonstrate an adaptation that supports participation.',practice:'Learners propose an accessible version of the task, agree a clear stop signal and explain how their adaptation preserves the learning goal. Demonstration may be seated, verbal or diagram-based.',check:'Assess inclusion, consent, safe control and a justified adaptation, not competitive fitness.'},
 ],
 creative:[
  {name:'Explore and explain',goal:'Make an intentional creative choice and describe it.',practice:'Model one possibility without setting it as the only correct outcome. Learners explore the materials or expressive forms safely, create a small example and explain one choice.',check:'Look for a purposeful choice and a connection to the theme, not imitation of the teacher’s style.'},
  {name:'Compare creative choices',goal:'Compare two creative approaches and explain their effects.',practice:'Learners try two arrangements, sounds, gestures or story choices appropriate to this task, compare their effects and select one with a reason. Offer equivalent accessible media.',check:'Check the comparison against the creator’s intention and respect different defensible interpretations.'},
  {name:'Develop and refine',goal:'Refine an original creative response after useful feedback.',practice:'Learners plan an original response, ask a partner for specific feedback and revise one feature while preserving their intention. Explain the change using the actual work.',check:'Assess intentional process, a justified revision and respectful response rather than cost or realism.'},
 ],
 practical:[
  {name:'Model, trace and try',goal:'Explain a task sequence and test a safe example.',practice:'Model the task using paper or a disposable classroom example. Learners trace the steps, identify the intended result and make an independent attempt without touching real accounts, files or unsafe tools.',check:'Check that the method reaches the intended result under the stated conditions.'},
  {name:'Test and improve',goal:'Use a test to identify an issue and make a justified improvement.',practice:'Learners compare their result with a stated criterion, record an actual issue and revise one step or feature. Use fictional data, safe materials and paper-first alternatives.',check:'Require a connection between the observed issue, the change and the result of a second check.'},
  {name:'Design and evaluate',goal:'Plan a solution, test it and explain a limitation.',practice:'Learners propose a small safe solution, state a success criterion, test a paper or disposable model and evaluate a limitation. Explain how the design could be improved without real purchases or external actions.',check:'Assess criteria, test evidence, safe process and a realistic limitation.'},
 ]};
function practiceFor(subject,band,n){
 const index=(n-1)%3;
 if(['ghanaian-language','french-language','arabic'].includes(subject.slug))return practiceFamilies.language[index];
 if(subject.slug.startsWith('physical-education'))return practiceFamilies.movement[index];
 if(subject.slug.startsWith('creative-arts'))return practiceFamilies.creative[index];
 if(['computing','career-technology'].includes(subject.slug))return practiceFamilies.practical[index];
 return stages[band][index];
}
function makeSubjectPack(level,subject){
 const n=Number(level.slug.split('-')[1]);const band=n<=3?'lower':n<=6?'upper':'jhs';const step=practiceFor(subject,band,n);
 const base=subject.slug==='english-language'?{title:band==='lower'?'Listening, reading and sentence building':band==='upper'?'Reading, writing and communication':'Communication, evidence and composition',strand:'Oral language, reading and writing',rows:band==='lower'?englishLower:band==='upper'?englishUpper:englishJhs,resources:'Original short texts provided in the activities, picture prompts, word cards, paper and optional communication aids.'}:units[aliases[subject.slug]||subject.slug];
 if(!base)throw new Error(`Missing subject unit: ${subject.slug}`);
 const label=n<=6?`Primary ${n}`:`JHS ${n-6}`;
 const id=`${level.slug}-${subject.slug}-enrichment-v1`;
 const weeks=base.rows.map(([topic,outcome,activity,task,check],index)=>({week:index+1,durationMinutes:subject.slug.startsWith('physical-education')?40:60,topic,strand:base.strand,subStrand:topic,contentStandard:'',indicator:'',performanceIndicator:`${outcome} ${step.goal}`,coreCompetencies:'Communication and collaboration; critical thinking and problem solving; personal development.',resources:base.resources,keywords:topic.replaceAll(' and ', ', '),
  starter:`Introduce “${topic}” with a picture, short model or fictional situation from the activity. Ask learners what they notice and record one starting idea without marking it correct immediately.`,
  mainActivity:`${activity} Class practice target — ${step.name}: ${step.practice} Provide a communication aid, large print or an oral alternative where needed.`,
  assessment:`${task} Teacher check: ${check} ${step.check} Assess the subject skill separately from handwriting, confidence or access to materials.`,
  plenary:'Invite two supported responses, revisit the starting idea and ask each learner to show or explain one improvement and one next step.',reflection:''}));
 return {id,version:`edupal-content:${id}`,title:`${label} ${subject.name} · ${base.title}`,classId:level.slug,subjectId:subject.slug,subjectName:subject.name,weekCount:12,sourceUrl:n<=6?'https://nacca.gov.gh/learning-areas-subjects/new-standards-based-curriculum-2019/':'https://nacca.gov.gh/common-core-programme-ccp/',sourceTitle:n<=6?'NaCCA Primary curriculum collection':'NaCCA Common Core Programme curriculum collection',reviewStatus:'Teacher review required',notice:`Original EduPalGh ${subject.name} teaching unit with ${label} practice targets. Suggested 12-week unit; not an official term schedule or a complete yearly course. Related classes share unit themes with different scaffolding and assessment expectations; exact standards and indicators require teacher verification.${base.local?' '+base.local:''}`,weeks};
}
export const OTHER_SUBJECT_PACKS=GHANA_LEVELS.filter(level=>level.slug.startsWith('basic-')).flatMap(level=>level.subjects.filter(subject=>subject.slug!=='mathematics').map(subject=>makeSubjectPack(level,subject)));
